-- Candidate migration; do not run on a live database without independent release approval.
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','suspended')) DEFAULT 'active');
CREATE TABLE IF NOT EXISTS identities (id TEXT PRIMARY KEY, issuer TEXT NOT NULL, external_sub TEXT NOT NULL, UNIQUE(issuer,external_sub));
CREATE TABLE IF NOT EXISTS memberships (tenant_id TEXT NOT NULL REFERENCES tenants(id), identity_id TEXT NOT NULL REFERENCES identities(id), role TEXT NOT NULL CHECK(role IN ('owner','admin','member','viewer')), status TEXT NOT NULL CHECK(status IN ('active','revoked')) DEFAULT 'active', PRIMARY KEY(tenant_id,identity_id));
CREATE TABLE IF NOT EXISTS price_catalog (id TEXT PRIMARY KEY, name TEXT NOT NULL, currency TEXT NOT NULL, amount_minor INTEGER NOT NULL CHECK(amount_minor>0), grant_units INTEGER NOT NULL CHECK(grant_units>0), enabled INTEGER NOT NULL CHECK(enabled IN (0,1)) DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), identity_id TEXT NOT NULL REFERENCES identities(id), price_id TEXT NOT NULL REFERENCES price_catalog(id), amount_minor INTEGER NOT NULL CHECK(amount_minor>0), currency TEXT NOT NULL, grant_units INTEGER NOT NULL CHECK(grant_units>0), state TEXT NOT NULL CHECK(state IN ('pending','settled','void')) DEFAULT 'pending', client_key TEXT NOT NULL, provider_checkout_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,client_key), UNIQUE(provider_checkout_id));
CREATE TABLE IF NOT EXISTS provider_events (event_id TEXT PRIMARY KEY, provider TEXT NOT NULL, provider_transaction_id TEXT NOT NULL, order_id TEXT NOT NULL REFERENCES orders(id), kind TEXT NOT NULL CHECK(kind IN ('settlement','refund')), amount_minor INTEGER NOT NULL CHECK(amount_minor>0), currency TEXT NOT NULL, verified_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(provider,provider_transaction_id,kind));
CREATE TABLE IF NOT EXISTS credit_ledger (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), delta INTEGER NOT NULL CHECK(delta!=0), source_key TEXT NOT NULL, event_id TEXT REFERENCES provider_events(event_id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,source_key));
CREATE INDEX IF NOT EXISTS ix_ledger_tenant ON credit_ledger(tenant_id);
CREATE TABLE IF NOT EXISTS holds (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), work_id TEXT, request_key TEXT NOT NULL, units INTEGER NOT NULL CHECK(units>0), state TEXT NOT NULL CHECK(state IN ('open','committed','released')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,request_key));
CREATE INDEX IF NOT EXISTS ix_hold_tenant_state ON holds(tenant_id,state);
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), currency TEXT NOT NULL, amount_minor INTEGER NOT NULL CHECK(amount_minor>0), tax_status TEXT NOT NULL DEFAULT 'tax_review_required', issued_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS refund_requests (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), order_id TEXT NOT NULL REFERENCES orders(id), identity_id TEXT NOT NULL REFERENCES identities(id), amount_minor INTEGER NOT NULL CHECK(amount_minor>0), reason TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('requested','rejected','provider_pending','settled')) DEFAULT 'requested', client_key TEXT NOT NULL, event_id TEXT UNIQUE REFERENCES provider_events(event_id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,client_key));
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, objective TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES identities(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_project_tenant ON projects(tenant_id);
CREATE TABLE IF NOT EXISTS work (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, desired_outcome TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','approved','running','verified','blocked')) DEFAULT 'draft', created_by TEXT NOT NULL REFERENCES identities(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_work_project ON work(tenant_id,project_id);
CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), work_id TEXT NOT NULL REFERENCES work(id), principal TEXT NOT NULL, scope TEXT NOT NULL, budget_units INTEGER NOT NULL CHECK(budget_units>=0), status TEXT NOT NULL DEFAULT 'inactive' CHECK(status IN ('inactive','active','revoked')));
CREATE TABLE IF NOT EXISTS artifacts (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), work_id TEXT NOT NULL REFERENCES work(id), kind TEXT NOT NULL, sha256 TEXT NOT NULL, storage_ref TEXT NOT NULL, evidence_state TEXT NOT NULL DEFAULT 'not_verified' CHECK(evidence_state IN ('not_verified','verified')));
CREATE TABLE IF NOT EXISTS evidence (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), work_id TEXT NOT NULL REFERENCES work(id), artifact_id TEXT REFERENCES artifacts(id), claim TEXT NOT NULL, evidence_sha256 TEXT NOT NULL, verifier_subject TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_evidence_work ON evidence(tenant_id,work_id);
